const txs = inputs.queryTxs.transactions ?? [];
const corpus = JSON.parse(inputs.loadCorpus.value ?? '{\"vectors\":[]}');
let maxScore = 0;
const signals = [];
for (const tx of txs) {
  const resp = await fetch(`${env.PHULAX_CLASSIFIER_URL}/classify`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ tx, corpus })
  });
  const out = await resp.json();
  signals.push({ hash: tx.hash, p: out.p_nefarious, model_hash: out.model_hash, input_hash: out.input_hash, signature: out.signature });
  if (out.p_nefarious > maxScore) maxScore = out.p_nefarious;
}
return { maxScore, signals };
